content.text:
请对以下 case 进行三维加权评分。

=== case_id ===
Case-25-reading-005

=== 用户原始指令 (query.txt) ===
阅读完成比例，一行显示距离目标还差多少，点一下跳进app，顺便读天气，提示我快读不完了

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "阅读完成比例，一行显示距离目标还差多少，点一下跳进app，顺便读天气，提示我快读不完了",
  "size": "2x4",
  "eventCandidates": [
    {
      "call": "clickToDeeplink",
      "args": {
        "bundleName": "",
        "abilityName": "",
        "uri": "hww://www.huawei.com/totemweather?enterType=share&cityCode="
      }
    }
  ],
  "dataModelSchema": {
    "data": {
      "reading": {
        "progressValue": {
          "type": "number",
          "description": "阅读目标完成进度数值，按百分制表达。",
          "sampleValue": 72
        },
        "progressTotal": {
          "type": "number",
          "description": "阅读目标进度总量，按百分制表达。",
          "sampleValue": 100
        },
        "percentText": {
          "type": "string",
          "description": "阅读完成比例展示文本。",
          "sampleValue": "72%"
        },
        "caption": {
          "type": "string",
          "description": "阅读进度主数值的短说明。",
          "sampleValue": "阅读完成"
        },
        "remainingText": {
          "type": "string",
          "description": "距离阅读目标还差多少的单行展示文本。",
          "sampleValue": "距目标还差 42 页"
        },
        "warningText": {
          "type": "string",
          "description": "阅读目标可能无法按时完成时的风险提醒。",
          "sampleValue": "快读不完了"
        }
      },
      "weather": {
        "location": {
          "districtName": {
            "type": "string",
            "description": "天气查询的区县名称。",
            "sampleValue": "青浦区"
          }
        },
        "current": {
          "temperatureText": {
            "type": "string",
            "description": "当前温度展示文本。",
            "sampleValue": "29°C"
          },
          "condition": {
            "type": "string",
            "description": "当前天气现象。",
            "sampleValue": "多云"
          }
        }
      }
    }
  },
  "assetCandidates": [
    {
      "src": "resources/base/media/cloudy.png",
      "description": "云朵组合彩色天气图标，适合表达多云天气和轻量环境信息。"
    }
  ]
}

